"""
calc.py - 简单的四则运算计算器
用法: python calc.py "表达式"
示例: python calc.py "2+3*4"
"""

import sys
import ast
import operator

# 操作符 → 实际函数映射
OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
}


def eval_expr(node):
    """递归计算 AST 节点的值"""
    if isinstance(node, ast.Constant):
        return node.value

    if isinstance(node, ast.BinOp):
        left = eval_expr(node.left)
        right = eval_expr(node.right)
        op_func = OPERATORS.get(type(node.op))
        if op_func is None:
            raise ValueError(f"不支持的运算符: {type(node.op).__name__}")
        return op_func(left, right)

    if isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.USub):
            return -eval_expr(node.operand)
        if isinstance(node.op, ast.UAdd):
            return +eval_expr(node.operand)

    raise ValueError(f"不支持的语法节点: {type(node).__name__}")


def calc(expression):
    """解析并计算表达式"""
    tree = ast.parse(expression.strip(), mode='eval')
    return eval_expr(tree.body)


def main():
    if len(sys.argv) != 2:
        print("用法: python calc.py \"表达式\"")
        print("示例: python calc.py \"2+3*4\"")
        sys.exit(1)

    try:
        result = calc(sys.argv[1])
        print(result)
    except Exception as e:
        print(f"错误: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""CLI 待办管理工具 - 使用 JSON 文件存储待办事项"""

import json
import sys
import os

DATA_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "todo_data.json")


def load_todos():
    """从 JSON 文件加载待办列表"""
    if not os.path.exists(DATA_FILE):
        return []
    with open(DATA_FILE, "r", encoding="utf-8") as f:
        return json.load(f)


def save_todos(todos):
    """将待办列表保存到 JSON 文件"""
    with open(DATA_FILE, "w", encoding="utf-8") as f:
        json.dump(todos, f, ensure_ascii=False, indent=2)


def next_id(todos):
    """返回下一个可用的 ID"""
    if not todos:
        return 1
    return max(item["id"] for item in todos) + 1


def cmd_add(args):
    """添加新待办"""
    if len(args) < 1:
        print("用法: python todo_app.py add <任务描述>")
        return 1
    task = " ".join(args)
    todos = load_todos()
    todos.append({"id": next_id(todos), "task": task, "done": False})
    save_todos(todos)
    print(f"已添加待办: {task}")
    return 0


def cmd_done(args):
    """标记待办为已完成"""
    if len(args) < 1:
        print("用法: python todo_app.py done <ID>")
        return 1
    try:
        todo_id = int(args[0])
    except ValueError:
        print("错误: ID 必须是数字")
        return 1
    todos = load_todos()
    for item in todos:
        if item["id"] == todo_id:
            item["done"] = True
            save_todos(todos)
            print(f"已完成待办 {todo_id}: {item['task']}")
            return 0
    print(f"错误: 未找到 ID 为 {todo_id} 的待办")
    return 1


def cmd_list(args):
    """列出所有待办"""
    todos = load_todos()
    if not todos:
        print("暂无待办事项")
        return 0
    print(f"{'ID':<4} {'状态':<8} {'任务'}")
    print("-" * 40)
    for item in todos:
        status = "✓ 已完成" if item["done"] else "□ 未完成"
        print(f"{item['id']:<4} {status:<8} {item['task']}")
    return 0


def cmd_delete(args):
    """删除指定待办"""
    if len(args) < 1:
        print("用法: python todo_app.py delete <ID>")
        return 1
    try:
        todo_id = int(args[0])
    except ValueError:
        print("错误: ID 必须是数字")
        return 1
    todos = load_todos()
    for i, item in enumerate(todos):
        if item["id"] == todo_id:
            removed = todos.pop(i)
            save_todos(todos)
            print(f"已删除待办 {removed['id']}: {removed['task']}")
            return 0
    print(f"错误: 未找到 ID 为 {todo_id} 的待办")
    return 1


def main():
    if len(sys.argv) < 2:
        print("用法: python todo_app.py <命令> [参数...]")
        print("命令: add, done, list, delete")
        return 1

    command = sys.argv[1]
    args = sys.argv[2:]

    if command == "add":
        return cmd_add(args)
    elif command == "done":
        return cmd_done(args)
    elif command == "list":
        return cmd_list(args)
    elif command == "delete":
        return cmd_delete(args)
    else:
        print(f"未知命令: {command}")
        print("可用命令: add, done, list, delete")
        return 1


if __name__ == "__main__":
    sys.exit(main())

